func (c *Core) trixOpenAndFillInternal(inReal []float64, startIdx, optInTimePeriod int32, outBegIdx, outNBElement *int32, outReal []float64) (*TRIXStream, error) {
	sp := &TRIXStream{core: c}
	if retCode := c.trixOpenImpl(sp, inReal, startIdx, optInTimePeriod, outBegIdx, outNBElement, outReal, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) trixOpenInternal(inReal []float64, startIdx, optInTimePeriod int32) (*TRIXStream, error) {
	sp := &TRIXStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outReal [1]float64
	if retCode := c.trixOpenImpl(sp, inReal, startIdx, optInTimePeriod, &outBegIdx, &outNBElement, sink_outReal[:], 0); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// TRIXOpen opens a live [TRIXStream] on a warm-up history, oldest bar first,
// and returns it with its value at the last history bar, the value [Core.TRIX]
// writes there.
//
// inReal is the history; the parameters are those of [Core.TRIX].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.TRIXLookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for a parameter out of range.
func (c *Core) TRIXOpen(inReal []float64, optInTimePeriod int) (*TRIXStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.trixOpenInternal(inReal, 0, int32(optInTimePeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// TRIXOpenAndFill opens a stream as [Core.TRIXOpen] does and also writes the
// outputs over the whole history, as [Core.TRIX] writes them for bars 0 through
// len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.TRIXLookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.TRIXOpen], and [BadParam] for an output that is
// empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) TRIXOpenAndFill(inReal []float64, optInTimePeriod int, outReal []float64) (*TRIXStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.trixLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && overlaps(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.trixOpenAndFillInternal(inReal, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
